<?php require_role('supervisor');$pageTitle='Milestone Reviews';$pageSubtitle='Approve submissions or request revision';$items=db_all("SELECT m.*,u.full_name student_name,u.matric_no,p.title project_title FROM milestones m JOIN projects p ON p.id=m.project_id JOIN users u ON u.id=p.student_id WHERE p.supervisor_id=? ORDER BY CASE WHEN m.status='submitted' THEN 0 ELSE 1 END,m.id",[current_user()['id']]);include __DIR__.'/../includes/layout_top.php'; ?>
<div class="card"><div class="card-header"><div><h2>Student milestone submissions</h2><p>Comments are immediately visible on the student dashboard.</p></div></div><div class="table-wrap"><table><thead><tr><th>Student / project</th><th>Milestone</th><th>Status</th><th>Student note</th><th>Review</th></tr></thead><tbody><?php foreach($items as $m):?><tr><td><strong><?= e($m['student_name']) ?></strong><br><span class="muted"><?= e($m['matric_no']) ?><br><?= e($m['project_title']) ?></span></td><td><strong><?= e($m['title']) ?></strong><br><?= (int)$m['weight'] ?>% weight</td><td><span class="badge <?= status_class($m['status']) ?>"><?= e(str_replace('_',' ',$m['status'])) ?></span></td><td><?= e($m['student_note']?:'No submission note') ?></td><td><form method="post" action="<?= e(url('actions.php')) ?>"><input type="hidden" name="csrf" value="<?= e(csrf_token()) ?>"><input type="hidden" name="action" value="review_milestone"><input type="hidden" name="milestone_id" value="<?= (int)$m['id'] ?>"><select name="status"><option value="approved">Approve</option><option value="revision">Request revision</option><option value="in_progress">Return to in progress</option></select><textarea name="supervisor_comment" style="min-height:70px" placeholder="Record precise academic feedback."><?= e($m['supervisor_comment']) ?></textarea><button class="button small" type="submit">Save review</button></form></td></tr><?php endforeach;?></tbody></table></div></div>
